const scenarioBank=[
{type:'Student misconception',title:'The confident misconception',context:'During an inquiry into living things, a student says: “Plants get all their food from the soil, so sunlight is only there to keep them warm.” Several classmates agree.',prompt:'What would you do next to uncover students’ thinking and help them investigate this idea without simply giving them the answer?',follow:'What evidence would show you whether their understanding has changed?'},
{type:'Unexpected line of inquiry',title:'The question that changes the plan',context:'Your class is exploring how communities use water. A student asks why some neighbourhoods flood after heavy rain while others nearby do not. Several students want to investigate this instead of continuing with the planned task.',prompt:'How would you decide whether and how to follow this question while keeping the unit’s central idea in view?',follow:'What would you discuss with colleagues before changing the sequence?'},
{type:'Learner needs',title:'Different ways to join the inquiry',context:'One learner has detailed ideas but avoids speaking in front of the group. Another speaks often but records very little evidence. Groups share findings tomorrow.',prompt:'How could you adapt participation and evidence-gathering so both learners contribute meaningfully without lowering the learning goal?',follow:'How would you check that the adaptation supports agency?'},
{type:'Assessment surprise',title:'A polished product, shaky understanding',context:'Students have made beautiful posters about connected habitats. In conversation, many cannot explain why removing one species might affect others.',prompt:'How would you respond to the gap between the finished product and students’ conceptual understanding?',follow:'What evidence would you gather next, and what might you change?'},
{type:'POI alignment challenge',title:'A tempting detour',context:'Your unit explores how people affect shared environments. Students become absorbed in building a recycling truck model, but most discussion is about decorating it.',prompt:'How would you reconnect the activity to the central idea and lines of inquiry without dismissing students’ enthusiasm?',follow:'When might an adaptation need discussion with the planning team?'}
];
const conceptList=['Form','Function','Causation','Change','Connection','Perspective','Responsibility'];
const sections:{key:keyof Plan;title:string;hint:string;placeholder:string;rows?:number}[]=[
{key:'centralIdea',title:'Central idea',hint:'What enduring understanding could students transfer beyond this unit? Aim for an idea, not just a topic or activity.',placeholder:'Example: Living things depend on relationships within their environments.',rows:3},
{key:'lines',title:'Lines of inquiry',hint:'Usually 2–3 pathways that help students investigate different aspects of the central idea.',placeholder:'1. Different needs within an environment\n2. How human choices affect living things\n3. Ways communities care for shared spaces',rows:4},
{key:'concepts',title:'Key concepts',hint:'Choose conceptual lenses that genuinely help students explore the big understanding.',placeholder:'Select concepts below or type them here.'},
{key:'learnerProfile',title:'Learner profile attributes',hint:'Which attributes might students practise and demonstrate? Explain them through learning, not just labels.',placeholder:'e.g. Inquirers, Thinkers, Caring'},
{key:'atl',title:'Approaches to learning (ATL)',hint:'Make transferable skills explicit: thinking, communication, research, social or self-management.',placeholder:'What skill will students practise, and how will you teach it?',rows:3},
{key:'priorKnowledge',title:'Prior knowledge and student questions',hint:'What might students already know, believe or wonder? Leave room for their questions to shape the unit.',placeholder:'What do students already notice? What misconceptions might they have?',rows:3},
{key:'experiences',title:'Provocation and learning experiences',hint:'Begin with curiosity. Plan investigations and discussions, then revisit students’ thinking.',placeholder:'An object, local issue, walk, demonstration, image or surprising question…',rows:3},
{key:'assessment',title:'Evidence of learning',hint:'What will students say, make, do or explain to show understanding? Gather evidence throughout the unit.',placeholder:'Initial thinking, observation notes, student explanations, transfer task…',rows:3},
{key:'agency',title:'Student voice, choice and action',hint:'Where can students make meaningful decisions? Action can be small and connected to learning.',placeholder:'How might learners influence questions, choices or responsible action?',rows:3},
{key:'reflection',title:'Teacher reflection',hint:'Complete after teaching: what changed in students’ thinking, whose voice was heard, and what will you adapt?',placeholder:'Leave this for after the unit.',rows:3}
];
type Guide={title:string;summary:string;detail:string[];scenario:string;questions:string[];practice:string};
const guides:Guide[]=[
{title:'Transdisciplinary learning',summary:'Learning connects ideas across subject boundaries and helps children explore meaningful questions about the world. Subjects still contribute important knowledge and skills.',detail:['Transdisciplinary learning begins with a meaningful idea, issue or phenomenon that matters beyond a single subject. It creates opportunities to use knowledge and skills from language, mathematics, science, social studies, arts and other areas where they genuinely help learners understand the inquiry.','It does not mean removing subjects or making every lesson fit every subject. Teachers identify the disciplinary knowledge students need, then make purposeful connections that deepen understanding.','A strong inquiry makes room for student questions, evidence, different perspectives and transfer to situations beyond the original activity.'],scenario:'A class investigates the school canteen. Students survey food choices, calculate quantities and costs, interview staff, examine packaging and propose a change. The connections are useful because each subject helps them understand a real system—not because every subject must appear in every lesson.',questions:['What is worth understanding here beyond one subject?','Which subject knowledge and skills will genuinely deepen this inquiry?','Can students use what they learn in a new context?'],practice:'Choose one real-world question. Map the knowledge and skills needed to investigate it, then remove any subject connection that feels forced.'},
{title:'Central idea',summary:'A concise statement of an enduring understanding. It should invite exploration and be transferable beyond one activity, text or project.',detail:['The central idea expresses the conceptual understanding students are working toward. It is broader than a topic and more meaningful than a list of facts or activities. It should support different examples, viewpoints and questions while remaining clear enough to guide planning.','A useful test is transfer: could the understanding apply in another place, time or situation? The central idea should not reveal a single correct answer to a narrow factual question, and it should not be so broad that almost anything fits.','The central idea, lines of inquiry, learning experiences and assessment should align. If the planned activities do not help students explore the central idea, revisit the design.'],scenario:'Topic: bridges. Activity statement: “We will build bridges from paper.” This describes an activity. A more conceptual possibility is “Design choices are influenced by purpose, materials and constraints.” Students can investigate this understanding through different structures and real design problems.',questions:['Does this state an understanding or merely name a topic?','Could students explore it through more than one example or viewpoint?','Could the understanding transfer beyond this unit?','Do the lines of inquiry and assessment actually support it?'],practice:'Write a one-sentence central idea. Underline the key conceptual relationship, then test it against a second context unrelated to your first example.'},
{title:'Lines of inquiry',summary:'Pathways into the central idea, not a list of weekly activities. Each should open up a different aspect of the understanding.',detail:['Lines of inquiry break a central idea into complementary avenues for exploration. Together, they should give students several ways to develop the intended understanding rather than repeating the same question in different words.','They are not a fixed lesson sequence, a worksheet list or simply three topics. They can be refined as students’ questions and evidence reveal what needs more attention.','Plan questions, experiences, resources and assessment evidence for each line. Check that the lines are distinct but connected to the central idea.'],scenario:'Central idea: “Communities use systems to meet shared needs.” Possible lines: the purpose of community systems; how people and resources move through a system; how decisions affect who benefits. “Make a poster” is an activity, not a line of inquiry.',questions:['Does each line explore a different aspect of the central idea?','Are the lines conceptual enough to invite questions and evidence?','Could I identify experiences and evidence connected to each line?','Are any lines overlapping or disconnected from the central idea?'],practice:'Draft three lines. Give each a short label, explain how it differs from the others, and draw a connection from each one back to the central idea.'},
{title:'Key concepts',summary:'Thinking lenses: form, function, causation, change, connection, perspective and responsibility. They help learners ask deeper questions.',detail:['Concepts are reusable lenses for thinking—not vocabulary words to memorise or boxes to tick. They help students move from describing examples toward explaining relationships, considering viewpoints and making reasoned judgments.','Form asks what something is like; function asks how it works; causation explores why something happens; change examines how things develop; connection looks at relationships; perspective considers different viewpoints; responsibility asks about obligations and possible responses.','Choose concepts because they help open up the central idea and lines of inquiry. A unit does not need to use every concept. Make the concept visible in teacher questions, student talk and evidence of understanding.'],scenario:'When studying playground design, form may help students describe features, function may examine how equipment is used, perspective may compare children’s needs, and responsibility may prompt discussion about access and safety.',questions:['Which concept would unlock deeper thinking in this unit?','What question would make that concept visible?','How might students use the same concept in a different context?'],practice:'Choose one key concept and write three questions: one to notice, one to explain, and one to transfer or evaluate.'},
{title:'Learner profile',summary:'Attributes describe the kind of learner the community aims to develop, including being inquiring, knowledgeable, caring and reflective.',detail:['The learner profile is intended to shape the learning community and how people learn together. It is more than a display of words or a label assigned to a student. Teachers can model attributes, notice them in action and invite learners to reflect on how they are developing.','Examples include being inquirers, knowledgeable, thinkers, communicators, principled, open-minded, caring, risk-takers, balanced and reflective. Select attributes that have a genuine connection to the learning and community needs.','Avoid using an attribute as a reward or as a fixed judgment of a child’s personality. Instead, identify observable choices, strategies and moments of growth.'],scenario:'A student changes their design after testing shows it is unstable. Rather than simply calling the student a risk-taker, the teacher asks what evidence informed the change and how the student reflected on the first attempt.',questions:['Which attribute could naturally be practised during this inquiry?','What action or evidence might show it developing?','How can students reflect on growth without being labelled?'],practice:'Select one or two relevant attributes. Write a student-friendly reflection prompt and identify what you might observe or hear.'},
{title:'Approaches to learning (ATL)',summary:'Transferable skills in thinking, communication, research, social interaction and self-management. They need explicit teaching and practice.',detail:['ATL skills help learners become more independent and effective. Students may need modelling, shared practice, feedback and repeated opportunities before they can use a skill independently.','Think about the actual skill inside a broad category: asking researchable questions, checking source reliability, explaining reasoning, listening actively, resolving disagreement, organising materials or reflecting on progress.','Plan where the skill will be introduced, practised and assessed. Do not assume students already know how to collaborate, research or manage time simply because the task requires it.'],scenario:'Students are asked to research local transport. Some copy the first webpage they find. The teacher pauses to model how to identify an author, compare sources, record evidence and paraphrase information before students continue.',questions:['Which specific skill will learners need to succeed?','What will I model or teach explicitly?','How will students practise with feedback before working independently?','What evidence will show that the skill is improving?'],practice:'Choose one ATL skill. Plan a short teacher model, a guided practice opportunity, a chance for independent use and one way to notice progress.'},
{title:'Agency, student voice and choice',summary:'Learners have meaningful opportunities to contribute ideas, make decisions, take action and influence parts of their learning.',detail:['Agency is not simply allowing students to choose a colour or activity. It includes meaningful participation in learning: asking questions, sharing ideas, making informed choices, taking responsibility and reflecting on the effects of decisions.','Teachers still provide structure, curriculum intent, safety and support. The aim is not to hand every decision to children, but to design authentic choices that learners can understand and influence.','Student voice should affect what happens next when possible. Gather questions and feedback, respond to them, and explain when a suggestion cannot be followed. Assessment can include student reflection and evidence of growing independence.'],scenario:'The class notices that younger students struggle to find books in the library. Students investigate the problem and propose several possible changes. The teacher helps them compare feasibility and consult the librarian; the class then tests one agreed improvement.',questions:['Which decisions can students genuinely influence?','How will their questions shape the next steps?','What support will help them make informed choices?','How will we show students that their voice was heard?'],practice:'Identify one decision in your next unit that students could help make. Define the boundaries, choices available and how the class will review the outcome.'},
{title:'Assessment and evidence of learning',summary:'Assessment helps reveal what learners know, understand and can do—and gives teachers information to adapt the next steps.',detail:['Assessment is part of the inquiry, not only a final test or product. Use initial evidence to understand prior knowledge, formative evidence to decide what to do next, and summative evidence to consider how well students can apply their learning.','Collect evidence aligned with the central idea, lines of inquiry and learning goals. Evidence may include explanations, discussion, observations, drafts, performances, designs, reflections or written work. A polished product alone may not reveal each learner’s understanding.','Use evidence to adjust teaching, revisit misconceptions, offer feedback and plan next steps. Involve students in understanding success criteria and reflecting on progress.'],scenario:'Groups create impressive posters about reducing waste, but conversations reveal that some students cannot explain why certain materials are recyclable. The teacher uses a short sorting task and student explanations to decide what needs reteaching.',questions:['What understanding do I need evidence of?','What could students say, make or do that would reveal it?','How will I distinguish group-product quality from individual understanding?','What might I change in response to the evidence?'],practice:'For one learning goal, list two different ways students could show understanding. Decide what evidence you will look for and what you will do if it is not yet visible.'},
{title:'Reflection and responsive teaching',summary:'A unit plan is a working document. Teachers revisit it as student questions, learning evidence and classroom realities emerge.',detail:['Planning gives direction, but a good inquiry does not have to follow a script. Student questions, misconceptions, new opportunities and assessment evidence may suggest a change in pace, resources or the sequence of experiences.','Record significant observations while teaching: what surprised you, whose voices were heard, which ideas need more time, and what evidence suggests students are ready to move on. Reflection is most useful when it informs a concrete next step.','After the unit, consider what supported learning, what needs revision and what should be carried forward. Keep the central idea and learning purpose in view while being willing to adapt the route.'],scenario:'The class becomes deeply interested in how the school uses water after noticing a leaking tap. The teacher connects the questions to the unit’s existing focus on shared resources, gathers relevant evidence and adapts the planned sequence instead of dismissing the interest as a distraction.',questions:['What have students shown or asked that should influence tomorrow’s learning?','What evidence suggests we should pause, extend or move on?','Whose perspectives or needs may be missing?','What one change will I make and why?'],practice:'After a lesson, write one observation, what it may mean for learning, and one specific next action. Revisit it at the next planning checkpoint.'}
];
