function App(){
 const [plan,setPlan]=useState<Plan>(()=>{try{return {...blank,...JSON.parse(localStorage.getItem('pyp-planner-draft')||'{}')}}catch{return blank}});
 const [currentDraftKey,setCurrentDraftKey]=useState('');
 const [unitDrafts,setUnitDrafts]=useState<Record<string,Plan>>(()=>{try{return JSON.parse(localStorage.getItem('pyp-planner-unit-drafts')||'{}')}catch{return {}}});
 const [poiEntries,setPoiEntries]=useState<PoiEntry[]>(()=>{try{return JSON.parse(localStorage.getItem('pyp-planner-poi')||'null')||samplePoi}catch{return samplePoi}});
 const [poiYear,setPoiYear]=useState('All year groups'); const [poiTheme,setPoiTheme]=useState('All themes'); const [editingPoi,setEditingPoi]=useState<number|null>(null);
 const [scenario,setScenario]=useState<typeof scenarioBank[number]|null>(null); const [scenarioAnswer,setScenarioAnswer]=useState(''); const [scenarioReflection,setScenarioReflection]=useState('');
 const [scenarioHistory,setScenarioHistory]=useState<{scenario:string;answer:string;reflection:string;date:string}[]>(()=>{try{return JSON.parse(localStorage.getItem('pyp-planner-scenarios')||'[]')}catch{return []}});

 const [page,setPage]=useState('Overview'); const [printChoice,setPrintChoice]=useState('all'); const [help,setHelp]=useState<string|null>(null); const [notice,setNotice]=useState('');
 const [openGuide,setOpenGuide]=useState<number|null>(null);
 const [suggestion,setSuggestion]=useState<{plan:Partial<Plan>;lessons:Lesson[]}|null>(null); const [sourceSnapshot,setSourceSnapshot]=useState(''); const [lessons,setLessons]=useState<Lesson[]>(()=>{try{return JSON.parse(localStorage.getItem('pyp-planner-lessons')||'null')||starterLessons}catch{return starterLessons}});
 useEffect(()=>{localStorage.setItem('pyp-planner-draft',JSON.stringify(plan))},[plan]);
 useEffect(()=>{localStorage.setItem('pyp-planner-unit-drafts',JSON.stringify(unitDrafts))},[unitDrafts]);
 useEffect(()=>{if(currentDraftKey){setUnitDrafts(items=>({...items,[currentDraftKey]:plan}));localStorage.setItem('pyp-planner-unit-drafts',JSON.stringify({...unitDrafts,[currentDraftKey]:plan}))}},[plan,currentDraftKey]);
 useEffect(()=>{localStorage.setItem('pyp-planner-lessons',JSON.stringify(lessons))},[lessons]);
 useEffect(()=>{localStorage.setItem('pyp-planner-poi',JSON.stringify(poiEntries))},[poiEntries]);
 useEffect(()=>{localStorage.setItem('pyp-planner-scenarios',JSON.stringify(scenarioHistory))},[scenarioHistory]);
 const updatePoi=(id:number,key:keyof PoiEntry,value:string)=>setPoiEntries(items=>items.map(item=>item.id===id?{...item,[key]:value}:item));
 const addPoi=()=>{const id=Math.max(0,...poiEntries.map(x=>x.id))+1;setPoiEntries(items=>[...items,{id,year:'Year 3',theme:themes[0],title:'New inquiry unit',centralIdea:'',lines:'',status:'Draft',timing:'To be decided'}]);setEditingPoi(id);};
 const loadMissingSamplePoi=()=>{setPoiEntries(current=>{const existingSlots=new Set(current.map(p=>p.year+'||'+p.theme));let nextId=Math.max(0,...current.map(p=>p.id))+1;const missing=samplePoi.filter(p=>!existingSlots.has(p.year+'||'+p.theme)).map(p=>({...p,id:nextId++}));return [...current,...missing]})};
 const missingSamplePoiCount=samplePoi.filter(p=>!poiEntries.some(existing=>existing.year===p.year&&existing.theme===p.theme)).length;
 const loadPoi=(p:PoiEntry)=>{const key=p.year+'||'+p.theme;const saved=(()=>{try{return JSON.parse(localStorage.getItem('pyp-planner-unit-drafts')||'{}') as Record<string,Plan>}catch{return {}}})();const existing=saved[key]||unitDrafts[key];const next=existing?existing:{...blank,title:p.title,year:p.year,theme:p.theme,centralIdea:p.centralIdea,lines:p.lines};setCurrentDraftKey(key);setPlan(next);setPage('Unit planner');setNotice(existing?'Reopened your saved unit draft. Continue where you left off.':'Started a new unit draft from this POI entry. Your other unit drafts remain saved separately.');};
 const deleteUnitDraft=(key:string)=>{const draft=unitDrafts[key];if(!window.confirm('Delete the saved draft “'+(draft?.title||'Untitled unit')+'”? This cannot be undone.'))return;const next={...unitDrafts};delete next[key];setUnitDrafts(next);localStorage.setItem('pyp-planner-unit-drafts',JSON.stringify(next));if(currentDraftKey===key){setCurrentDraftKey('');setPlan(blank)}setNotice('Saved unit draft deleted.');};
 const generateScenario=()=>{const pool=scenarioBank.filter(x=>x.title!==scenario?.title);setScenario(pool[Math.floor(Math.random()*pool.length)]||scenarioBank[0]);setScenarioAnswer('');setScenarioReflection('');};
 const saveScenario=()=>{if(!scenario||!scenarioAnswer.trim()){setNotice('Write your response before saving.');return;}setScenarioHistory(items=>[{scenario:scenario.type+' — '+scenario.title+'\n'+scenario.context,answer:scenarioAnswer,reflection:scenarioReflection,date:new Date().toLocaleDateString()},...items]);setScenario(null);setNotice('Your scenario response was saved in this browser.');};

 const update=(key:keyof Plan,value:string)=>setPlan(p=>({...p,[key]:value}));
 const makeSuggestions=()=>{
  const topic=(plan.context.trim()||plan.title.trim()||'our local environment').replace(/[.!?]+$/,'');
  const central=plan.centralIdea.trim()||`Living things and people are connected through the environments they share.`;
  const theme=plan.theme||'Sharing the planet';
  const p:Partial<Plan>={
   centralIdea:central,
   lines:`1. The needs and relationships of living things\n2. How choices can affect shared environments\n3. Ways people respond to changes in their communities`,
   concepts:plan.concepts.trim()||'Connection, Causation, Responsibility',
   learnerProfile:plan.learnerProfile.trim()||'Inquirers, Thinkers, Caring',
   atl:plan.atl.trim()||'Research: observe, gather information and compare sources. Thinking: identify relationships and support ideas with evidence. Communication: explain findings and listen to different perspectives.',
   priorKnowledge:plan.priorKnowledge.trim()||`Invite learners to share what they already know about “${topic}”, what they have noticed in their community, and what they wonder. Capture questions before introducing explanations.`,
   experiences:plan.experiences.trim()||`Begin with a local provocation connected to “${topic}” (a photograph, object, short walk or surprising example). Let learners generate questions, then group questions into areas to investigate.`,
   assessment:plan.assessment.trim()||'Gather initial thinking, observation notes and student explanations during inquiry. For a transfer task, ask learners to explain a relationship they investigated and support their explanation with evidence.',
   agency:plan.agency.trim()||'Invite learners to propose questions, choose a source or investigation method, and decide how to share one finding. Consider small, learner-led actions only when they follow naturally from the evidence.',
   learningGoals:plan.learningGoals.trim()||`Learners will investigate “${topic}”, make connections, and explain their thinking using observations or evidence.`,
   successCriteria:plan.successCriteria.trim()||'I can ask a useful question, gather relevant evidence, explain a connection, listen to another perspective and reflect on how my thinking changed.'
  };
  const ls:Lesson[]=[
   {id:1,title:'Provocation: notice and wonder',inquiry:'What do we notice, and what do we wonder about '+topic+'?',experience:'Share a local image, object, short walk or real example connected to '+topic+'. Learners record observations and generate questions before researching answers.',evidence:'Initial explanations, student questions and ideas to revisit later.',choice:'Learners choose which question they most want to investigate.'},
   {id:2,title:'Investigate relationships',inquiry:'What is connected, and how do we know?',experience:'Learners observe, read, interview or compare sources to investigate one question. Model how to distinguish an observation from an assumption.',evidence:'Notes, labelled diagrams, source comparisons and evidence-based explanations.',choice:'Learners suggest sources, roles or ways to record findings.'},
   {id:3,title:'Compare perspectives',inquiry:'Why might people understand this differently?',experience:'Compare findings and consider how experiences or needs shape different perspectives. Return to the central idea and lines of inquiry.',evidence:'Discussion contributions and revised explanations supported by examples.',choice:'Learners choose a perspective or finding to examine more closely.'},
   {id:4,title:'Apply and transfer understanding',inquiry:'Can we use our understanding in a new situation?',experience:'Present a new case, design challenge or local scenario. Learners use what they found out to explain a relationship or propose a response.',evidence:'A short explanation, model, presentation or solution with reasons.',choice:'Learners choose an appropriate format to demonstrate understanding.'},
   {id:5,title:'Reflect and consider action',inquiry:'How has our thinking changed, and what might we do next?',experience:'Revisit initial questions and compare first thoughts with current understanding. Discuss possible responses without assuming one action suits everyone.',evidence:'Before-and-after thinking, reflection and questions that remain unanswered.',choice:'Learners identify a next question or a realistic, responsible action.'}
  ];
  setSuggestion({plan:p,lessons:ls});setSourceSnapshot(JSON.stringify({theme:plan.theme,context:plan.context,title:plan.title,centralIdea:plan.centralIdea}));setNotice('Suggestions prepared from your current choices. Review them before applying.');
 };
 const applySuggestions=(replaceExisting:boolean)=>{
  if(!suggestion)return;
  setPlan(current=>{const next={...current};(Object.keys(suggestion.plan) as (keyof Plan)[]).forEach(key=>{const value=suggestion.plan[key];if(typeof value==='string'&&(replaceExisting||!String(current[key]||'').trim()))(next as any)[key]=value;});return next;});
  if(replaceExisting||lessons.every(l=>!l.experience.trim()))setLessons(suggestion.lessons);
  setSuggestion(null);setNotice(replaceExisting?'Suggestions applied. Review all updated fields and lessons.':'Suggestions added to empty fields; your existing writing was preserved.');
 };
 const started=useMemo(()=>[plan.theme,plan.centralIdea,plan.lines,plan.concepts,plan.atl,plan.assessment].filter(v=>v.trim()).length,[plan]);
 const exportPlan=()=>{const text=['TWOWISEOLDOWLS · PERSONAL PYP PLANNING WORKBOOK',plan.title,'',`Year group: ${plan.year}`,`Theme: ${plan.theme}`,`Duration: ${plan.duration}`,'',...sections.map(s=>s.title.toUpperCase()+'\n'+(plan[s.key]||'Not yet completed')),'PLANNING CONTEXT\n'+(plan.context||'Not yet completed'),'LEARNING GOALS\n'+(plan.learningGoals||'Not yet completed'),'SUCCESS CRITERIA\n'+(plan.successCriteria||'Not yet completed'),'RESOURCES AND PREPARATION\n'+(plan.resources||'Not yet completed'),'TEACHING NOTES\n'+(plan.teachingNotes||'Not yet completed'),'EVIDENCE COLLECTED\n'+(plan.evidenceCollected||'Not yet completed'),'STUDENT VOICE\n'+(plan.studentVoice||'Not yet completed'),'NEXT STEPS\n'+(plan.nextSteps||'Not yet completed'),'LESSON SEQUENCE',...lessons.flatMap((l,i)=>['Experience '+(i+1)+': '+l.title,'Inquiry question: '+l.inquiry,'Learning experience: '+l.experience,'Evidence: '+l.evidence,'Student voice and choice: '+l.choice,''])].join('\n\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='pyp-unit-plan.txt';a.click();URL.revokeObjectURL(url);setNotice('Draft exported.');};
 const save=()=>{localStorage.setItem('pyp-planner-draft',JSON.stringify(plan));localStorage.setItem('pyp-planner-lessons',JSON.stringify(lessons));setNotice('Draft saved in this browser.');};
 const updateLesson=(id:number,key:keyof Lesson,value:string)=>setLessons(items=>items.map(item=>item.id===id?{...item,[key]:value}:item));
 const addLesson=()=>setLessons(items=>[...items,{id:Math.max(0,...items.map(x=>x.id))+1,title:'New learning experience',inquiry:'',experience:'',evidence:'',choice:''}]);
 const removeLesson=(id:number)=>setLessons(items=>items.filter(item=>item.id!==id));
 const mentorChecks=[
  {title:'A purposeful transdisciplinary theme',ok:!!plan.theme,tip:plan.theme?'Ask whether this theme helps learners explore the central understanding, rather than simply naming the topic.':'Choose the theme that best frames the big understanding you want learners to explore.',page:'Unit planner',label:'Review theme'},
  {title:'A transferable central idea',ok:plan.centralIdea.trim().split(/\s+/).filter(Boolean).length>=7,tip:plan.centralIdea.trim().split(/\s+/).filter(Boolean).length>=7?'Read the central idea without the unit title. Could it still make sense in another place, context or time?':'Draft a complete statement of understanding. Avoid making it only a topic, question or activity; then ask whether it could transfer beyond this unit.',page:'Unit planner',label:'Review central idea'},
  {title:'Distinct pathways for inquiry',ok:plan.lines.trim().split(/\n/).filter(x=>x.trim()).length>=2,tip:plan.lines.trim().split(/\n/).filter(x=>x.trim()).length>=2?'Check that each line opens a different pathway into the central idea, rather than repeating the same idea or listing activities.':'Draft two or three distinct lines of inquiry that help learners explore different aspects of the central idea.',page:'Unit planner',label:'Review lines of inquiry'},
  {title:'Concepts and skills are purposeful',ok:!!plan.concepts.trim()&&!!plan.atl.trim(),tip:!plan.concepts.trim()?'Select concepts that genuinely help learners think more deeply about the central idea.':!plan.atl.trim()?'Name specific approaches to learning skills and how learners will practise them explicitly.':'For each concept and ATL skill, ask: where will learners use this, and what evidence will show their growth?',page:'Unit planner',label:'Review concepts and ATL'},
  {title:'Learning experiences build understanding',ok:lessons.length>=3&&lessons.filter(l=>l.inquiry.trim()&&l.experience.trim()).length>=3,tip:lessons.length<3?'Plan a sequence that moves beyond a single activity: invite questions, investigate, connect ideas, apply understanding and reflect.':lessons.filter(l=>l.inquiry.trim()&&l.experience.trim()).length<3?'Add an inquiry question and a meaningful student experience to at least three steps in your sequence.':'Look across the sequence: does it progress from prior thinking through investigation towards application and reflection? Keep room to respond to student questions.',page:'Lesson sequence',label:'Review experiences'},
  {title:'Assessment reveals understanding',ok:!!plan.assessment.trim()&&lessons.some(l=>l.evidence.trim()),tip:!plan.assessment.trim()?'Plan formative assessment throughout the unit and consider what final evidence would show understanding, not just task completion.':'Connect the overall assessment plan to the evidence you will notice during individual learning experiences. What will students say, do, make or explain?',page:'Teach & review',label:'Review evidence'},
  {title:'Student agency is more than participation',ok:!!plan.agency.trim()&&!!plan.studentVoice.trim(),tip:!plan.agency.trim()?'Identify specific decisions students can influence, such as questions, investigation methods, collaborators or ways to demonstrate learning.':'Compare your intended student choice with what students actually asked, decided or changed. Record how their thinking influenced the learning.',page:'Teach & review',label:'Review agency'},
  {title:'Reflection informs the next cycle',ok:!!plan.reflection.trim()&&!!plan.nextSteps.trim(),tip:'After teaching, use evidence to identify what learners understood, what remains uncertain and what you will adapt or investigate next.',page:'Teach & review',label:'Reflect after teaching'}
 ];

 return <div className="shell"><aside className="sidebar"><div className="brand"><span className="brandIcon owlMark"><OwlMark/></span><div><b>TwoWiseOldOwls</b><small>IB PYP planning studio</small></div></div><p className="sideLabel">WORKSPACE</p>{[{n:'Overview',i:Compass},{n:'Programme of Inquiry',i:Map},{n:'Planning journey',i:Sprout},{n:'Unit planner',i:BookOpen},{n:'Lesson sequence',i:Sparkles},{n:'Scenario Lab',i:Shuffle},{n:'Teach & review',i:CheckCircle2},{n:'Learning guide',i:GraduationCap},{n:'Quality check',i:Target}].map(x=><button key={x.n} className={'nav '+(page===x.n?'active':'')} onClick={()=>setPage(x.n)}><x.i size={17}/>{x.n}</button>)}<div className="sideBottom"><Sparkles size={17}/><div><b>Beginner mode</b><small>Learn as you plan</small></div></div></aside>
 <main><header className="topbar"><span>My workspace　/　<b>{page}</b></span><div><button className="btn light" onClick={exportPlan}><Download size={15}/> Export all</button><button className="btn light" onClick={()=>setPage("Print plan")}><BookOpen size={15}/> Print preview</button><button className="btn primary" onClick={save}><Save size={15}/> Save draft</button></div></header>
 {notice&&<button className="notice" onClick={()=>setNotice('')}>{notice}　×</button>}
 {page==='Programme of Inquiry'&&<div className="page narrow"><section className="poiPrintSheet"><div className="poiPrintMasthead"><div className="poiPrintBrandLockup"><div className="poiPrintLogo"><OwlMark/></div><div><div className="poiPrintBrand">TwoWiseOldOwls <span>·</span> PYP PLANNING STUDIO</div><h1>Programme of Inquiry</h1><p>Years 1–6 <i>•</i> Whole-school overview <i>•</i> Illustrative planning framework</p></div><div className="poiPrintEdition">PYP<br/>CURRICULUM MAP</div></div><div className="poiPrintRule"></div></div><table className="poiPrintTable"><thead><tr><th className="themeCol">Transdisciplinary theme</th>{['Year 1','Year 2','Year 3','Year 4','Year 5','Year 6'].map(y=><th key={y}>{y}</th>)}</tr></thead><tbody>{themes.map((theme,ti)=><tr key={theme}><th className={'themeCell themeTone'+ti}><span>{theme}</span></th>{['Year 1','Year 2','Year 3','Year 4','Year 5','Year 6'].map(year=>{const p=poiEntries.find(x=>x.year===year&&x.theme===theme);return <td key={year}>{p?<><b className="poiPrintUnitTitle">{p.title}</b><p>{p.centralIdea}</p></>:<span className="poiPrintMissing">Unit to be planned</span>}</td>})}</tr>)}</tbody></table><div className="poiPrintFooter"><span>Working document · Adapt and review collaboratively for your school context</span><span>36 illustrative units · Not an official IB or school-approved POI</span></div></section><div className="intro"><div className="eyebrow">STEP 01 · SCHOOL-WIDE CURRICULUM MAP</div><h1>Programme of Inquiry</h1><p>A complete 36-unit illustrative POI framework: six transdisciplinary themes across Years 1–6. This is a learning model, not an official IB or school-approved POI; adapt and review it collaboratively for your context.</p><div className="heroActions"><button className="btn primary" onClick={addPoi}><Plus size={15}/> Add POI entry</button><button className="btn light" onClick={()=>{const previousTitle=document.title;document.title="POI - Two Wise Old Owls";window.addEventListener("afterprint",()=>{document.title=previousTitle},{once:true});window.print()}}><Download size={15}/> Print POI</button>{missingSamplePoiCount>0&&<button className="btn light" onClick={loadMissingSamplePoi}>Load missing example units ({missingSamplePoiCount})</button>}</div></div><div className="poiNotice"><Map size={18}/><div><b>Collaborative document</b><p>A real school's POI is developed and reviewed with colleagues. Use this workspace to practise and prepare questions, not to make school-wide changes alone.</p></div></div><div className="filterBar"><label>Year group<select value={poiYear} onChange={e=>setPoiYear(e.target.value)}><option>All year groups</option>{['Year 1','Year 2','Year 3','Year 4','Year 5','Year 6'].map(y=><option key={y}>{y}</option>)}</select></label><label>Theme<select value={poiTheme} onChange={e=>setPoiTheme(e.target.value)}><option>All themes</option>{themes.map(t=><option key={t}>{t}</option>)}</select></label><span>{poiEntries.filter(p=>(poiYear==='All year groups'||p.year===poiYear)&&(poiTheme==='All themes'||p.theme===poiTheme)).length} entries</span></div><div className="poiEntries">{poiEntries.filter(p=>(poiYear==='All year groups'||p.year===poiYear)&&(poiTheme==='All themes'||p.theme===poiTheme)).map(p=><section className="poiEntry" key={p.id}><div className="poiEntryHead"><div><small>{p.year} · {p.theme}</small><h2>{p.title||'Untitled inquiry'}</h2></div><div className="poiEntryActions"><button className="btn light" onClick={()=>setEditingPoi(editingPoi===p.id?null:p.id)}>{editingPoi===p.id?'Close editor':'Edit entry'}</button><button className="btn light" onClick={()=>loadPoi(p)}>Plan this unit <ChevronRight size={14}/></button><button className="iconBtn" title="Delete entry" onClick={()=>{if(window.confirm('Delete this entry?'))setPoiEntries(items=>items.filter(x=>x.id!==p.id))}}><Trash2 size={14}/></button></div></div><div className="poiMeta"><span>{p.status}</span><span>{p.timing}</span></div>{editingPoi===p.id?<div className="poiEdit"><div className="twoCols"><label className="field">Year group<select value={p.year} onChange={e=>updatePoi(p.id,'year',e.target.value)}>{['Early years','Year 1','Year 2','Year 3','Year 4','Year 5','Year 6','Mixed-age'].map(y=><option key={y}>{y}</option>)}</select></label><label className="field">Theme<select value={p.theme} onChange={e=>updatePoi(p.id,'theme',e.target.value)}>{themes.map(t=><option key={t}>{t}</option>)}</select></label></div><label className="field">Unit title<input value={p.title} onChange={e=>updatePoi(p.id,'title',e.target.value)}/></label><label className="field">Central idea<textarea rows={3} value={p.centralIdea} onChange={e=>updatePoi(p.id,'centralIdea',e.target.value)}/></label><label className="field">Lines of inquiry<textarea rows={4} value={p.lines} onChange={e=>updatePoi(p.id,'lines',e.target.value)}/></label><div className="twoCols"><label className="field">Status<select value={p.status} onChange={e=>updatePoi(p.id,'status',e.target.value)}>{['Practice example','Draft','Under review','School-approved'].map(v=><option key={v}>{v}</option>)}</select></label><label className="field">Timing / notes<input value={p.timing} onChange={e=>updatePoi(p.id,'timing',e.target.value)}/></label></div><small className="muted">Changes save automatically in this browser. This is an illustrative curriculum model; status labels are user-managed, not verified approvals.</small></div>:<div className="poiContent"><div><h3>Central idea</h3><p>{p.centralIdea||'Add a central idea.'}</p></div><div><h3>Lines of inquiry</h3><p>{p.lines||'Add lines of inquiry.'}</p></div></div>}</section>)}</div><div className="note"><Lightbulb/><div><b>Use the POI as your reference</b><p>Look for progression across year levels, repetition or gaps, and opportunities for meaningful inquiry. Then plan the actual unit against the selected entry.</p></div></div></div>}
 {page==='Overview'&&<div className="page"><section className="hero"><div className="eyebrow">TWO WISE OLD OWLS · YOUR PYP JOURNEY</div><h1>Good teaching starts<br/>with <em>good questions.</em></h1><p>Your personal PYP learning studio: understand the framework, design meaningful inquiry, and reflect on your practice — one step at a time.</p><div className="heroActions"><button className="btn primary big" onClick={()=>setPage('Unit planner')}><Plus size={16}/> Create a unit</button><button className="btn heroSecondary big" onClick={()=>setPage('Learning guide')}>Learn the PYP <ArrowUpRight size={15}/></button></div><div className="heroArt"><OwlMark/><span>Wonder leads to learning ✦</span></div></section><div className="sectionHeading"><div><h2>Where would you like to begin?</h2><p>Three clear paths. Move between them whenever you need.</p></div><span className="tag">YOUR WORKSPACE</span></div><div className="cards"><button className="dashCard" onClick={()=>setPage('Unit planner')}><BookOpen/><small>PATH 01 · CREATE</small><h3>{plan.title||'Untitled unit'}</h3><p>{plan.theme||'Choose a transdisciplinary theme to begin.'}</p><div className="progress"><span style={{width:(started/6*100)+'%'}}/></div><small>{started} of 6 foundations started　→ Continue</small></button><button className="dashCard" onClick={()=>setPage('Learning guide')}><GraduationCap/><small>PATH 02 · LEARN</small><h3>Understand the PYP</h3><p>Build your confidence with plain-English explanations of inquiry, concepts and agency.</p><b>Explore the basics →</b></button><button className="dashCard" onClick={()=>setPage('Quality check')}><Target/><small>PATH 03 · REFLECT</small><h3>Unit quality check</h3><p>Review inquiry, conceptual thinking, agency and evidence of learning.</p><b>Review your draft →</b></button></div><div className="note"><Lightbulb/><div><b>A helpful reminder</b><p>PYP planning is iterative. Student questions, discoveries and reflections can shape what happens next.</p></div></div></div>}
 {page==='Planning journey'&&<div className="page narrow"><div className="intro"><div className="eyebrow">YOUR END-TO-END WORKFLOW</div><h1>From first thoughts to reflection.</h1><p>Complete each online form in order. Revisit earlier decisions as you learn more about your students. Print the combined planning pack when you are ready.</p></div><section className="copilotPanel"><div className="copilotTop"><span className="copilotIcon"><Sparkles size={20}/></span><div><div className="eyebrow">CONNECTED PLANNING ASSISTANT</div><h2>Build the next steps from your ideas</h2><p>Use your current context, theme and central idea to draft connected suggestions. You stay in charge: review before applying, and your existing writing is protected unless you choose to replace it.</p></div></div><button className="btn primary" onClick={makeSuggestions}><Sparkles size={15}/> Suggest the next steps</button>{suggestion&&<div className="suggestionPreview"><div className="previewHead"><b>Review your draft suggestions</b><span className="tag">Based on current choices</span></div><p><b>Central idea:</b> {suggestion.plan.centralIdea}</p><p><b>Lines of inquiry:</b></p><pre>{suggestion.plan.lines}</pre><p><b>Learning sequence:</b> {suggestion.lessons.map((l,i)=>(i+1)+'. '+l.title).join(' · ')}</p><p className="muted">These are editable starting points, not official IB guidance. Review the wording and fit for your learners.</p><div className="actions"><button className="btn light" onClick={()=>setSuggestion(null)}>Discard</button><button className="btn light" onClick={()=>applySuggestions(false)}>Fill empty fields only</button><button className="btn primary" onClick={()=>applySuggestions(true)}>Replace with these suggestions</button></div></div>}{sourceSnapshot&&sourceSnapshot!==JSON.stringify({theme:plan.theme,context:plan.context,title:plan.title,centralIdea:plan.centralIdea})&&!suggestion&&<p className="staleNote">Your starting context or central idea has changed since the last suggestions. Generate a fresh set when you are ready; your current entries will remain untouched.</p>}</section><div className="journeySteps">{[{n:'01',title:'Know your learners and context',desc:'Start with curriculum expectations, student strengths, prior knowledge, interests and the real-world context.',page:'Unit planner',label:'Start with context'},{n:'02',title:'Design the unit of inquiry',desc:'Choose a theme, central idea, lines of inquiry, concepts, learner profile and ATL skills.',page:'Unit planner',label:'Design the unit'},{n:'03',title:'Plan learning experiences',desc:'Sequence provocations, investigations, connections, transfer and reflection. Leave room for student questions.',page:'Lesson sequence',label:'Plan experiences'},{n:'04',title:'Prepare to teach and gather evidence',desc:'Record learning goals, success criteria, materials, teaching notes and evidence noticed during learning.',page:'Teach & review',label:'Prepare and teach'},{n:'05',title:'Review and improve',desc:'Reflect on what students understood, whose voice shaped inquiry and what you will adapt next time.',page:'Teach & review',label:'Review learning'},{n:'06',title:'Print or export your planning pack',desc:'Preview the unit, learning sequence, teaching notes and reflection together before printing.',page:'Print plan',label:'Preview full pack'}].map(s=><section className="journeyStep" key={s.n}><span className="journeyNumber">{s.n}</span><div className="journeyCopy"><h3>{s.title}</h3><p>{s.desc}</p><button className="btn light" onClick={()=>setPage(s.page)}>{s.label}<ChevronRight size={14}/></button></div></section>)}</div><div className="note"><Lightbulb/><div><b>A cycle, not a one-way checklist</b><p>Student questions and assessment evidence may send you back to adjust the sequence or refine the central idea.</p></div></div></div>}{page==='Unit planner'&&<div className="page narrow"><div className="intro"><div className="eyebrow">UNIT BUILDER · BEGINNER MODE</div><h1>Build your unit of inquiry</h1><p>Work through the sections in your own time. Use the help icons to learn the purpose behind each decision.</p></div>{Object.keys(unitDrafts).length>0&&<section className="formSection"><h2><span><BookOpen size={16}/></span> Your saved unit drafts</h2><p className="muted">Each unit has its own draft. Open another one whenever you need; your work stays separate.</p><div className="draftList">{Object.entries(unitDrafts).map(([key,draft])=><div className="draftListRow" key={key}><button className="draftListItem" onClick={()=>{setCurrentDraftKey(key);setPlan(draft);setNotice('Reopened saved draft: '+draft.title)}}><span><b>{draft.title||'Untitled unit'}</b><small>{draft.year} · {draft.theme}</small></span><ChevronRight size={16}/></button><button className="draftDeleteBtn" title="Delete saved draft" aria-label={'Delete draft '+(draft.title||'Untitled unit')} onClick={()=>deleteUnitDraft(key)}><Trash2 size={16}/></button></div>)}</div></section>}<section className="formSection"><h2><span>01</span> Unit overview</h2><label className="field">Unit title<input value={plan.title} onChange={e=>update('title',e.target.value)}/></label><div className="twoCols"><label className="field">Year group<select value={plan.year} onChange={e=>update('year',e.target.value)}>{['Years 3–6','Year 1','Year 2','Year 3','Year 4','Year 5','Year 6','Mixed-age class'].map(v=><option key={v}>{v}</option>)}</select></label><label className="field">Duration<select value={plan.duration} onChange={e=>update('duration',e.target.value)}>{['3 weeks','4 weeks','5 weeks','6 weeks','7 weeks','8 weeks','9 weeks','10 weeks'].map(v=><option key={v}>{v}</option>)}</select></label></div><label className="field">Transdisciplinary theme <button className="help" onClick={()=>setHelp('Transdisciplinary theme')} type="button">ⓘ</button><select value={plan.theme} onChange={e=>update('theme',e.target.value)}><option value="">Choose a theme…</option>{themes.map(t=><option key={t}>{t}</option>)}</select><small>Choose the theme that best fits the big understanding, not just the activity.</small></label>{poiEntries.some(p=>p.year===plan.year&&p.theme===plan.theme)?<div className="alignmentBox"><b><Map size={15}/> POI reference found</b><p>{poiEntries.filter(p=>p.year===plan.year&&p.theme===plan.theme).map(p=>p.title).join(' · ')}</p><button className="btn light" type="button" onClick={()=>setPage('Programme of Inquiry')}>Review POI entry <ChevronRight size={13}/></button></div>:plan.theme&&plan.year!=='Years 3–6'&&plan.year!=='Mixed-age class'?<div className="alignmentWarning"><b>No matching POI entry yet</b><p>Check your school's POI or add the correct entry before finalising the unit.</p><button className="btn light" type="button" onClick={()=>setPage('Programme of Inquiry')}>Open POI</button></div>:null}</section><section className="formSection"><h2><span>02</span> Purpose and conceptual understanding</h2>{sections.slice(0,5).map(s=><label className="field" key={s.key}>{s.title} <button type="button" className="help" onClick={()=>setHelp(s.title)}>ⓘ</button>{s.key==='concepts'?<><input value={plan.concepts} onChange={e=>update('concepts',e.target.value)} placeholder={s.placeholder}/><div className="chips">{conceptList.map(c=><button type="button" className={plan.concepts.split(',').map(v=>v.trim()).includes(c)?'chosen':''} key={c} onClick={()=>update('concepts',plan.concepts.split(',').map(v=>v.trim()).filter(Boolean).includes(c)?plan.concepts.split(',').map(v=>v.trim()).filter(v=>v!==c).join(', '):[...plan.concepts.split(',').map(v=>v.trim()).filter(Boolean),c].join(', '))}>{c}</button>)}</div></>:<textarea rows={s.rows||2} value={plan[s.key]} onChange={e=>update(s.key,e.target.value)} placeholder={s.placeholder}/>}<small>{s.hint}</small></label>)}</section><section className="formSection"><h2><span>03</span> Plan for inquiry</h2>{sections.slice(5,9).map(s=><label className="field" key={s.key}>{s.title} <button type="button" className="help" onClick={()=>setHelp(s.title)}>ⓘ</button><textarea rows={s.rows||3} value={plan[s.key]} onChange={e=>update(s.key,e.target.value)} placeholder={s.placeholder}/><small>{s.hint}</small></label>)}</section><section className="formSection"><h2><span>04</span> Reflect and improve</h2>{sections.slice(9).map(s=><label className="field" key={s.key}>{s.title}<textarea rows={3} value={plan[s.key]} onChange={e=>update(s.key,e.target.value)} placeholder={s.placeholder}/><small>{s.hint}</small></label>)}</section><div className="actions"><button className="btn light" onClick={()=>setPage('Overview')}>Back to overview</button><button className="btn primary" onClick={save}><Save size={15}/> Save draft</button></div></div>}
 {page==='Lesson sequence'&&<div className="page narrow"><div className="intro"><div className="eyebrow">PLAN THE LEARNING JOURNEY</div><h1>From big ideas to classroom experiences.</h1><p>Sketch a possible sequence, not a fixed script. In inquiry-based planning, students’ questions and discoveries should influence what comes next.</p></div><div className="note"><Lightbulb/><div><b>Plan for learning, not just activities</b><p>For each experience, connect a worthwhile question to what students will do, what evidence you will notice, and where learners can exercise voice or choice.</p></div></div>{lessons.map((lesson,i)=><section className="formSection" key={lesson.id}><div className="lessonHead"><h2><span>{String(i+1).padStart(2,'0')}</span> Learning experience</h2><button className="removeLesson" onClick={()=>removeLesson(lesson.id)} aria-label="Remove lesson">Remove</button></div><label className="field">Working title<input value={lesson.title} onChange={e=>updateLesson(lesson.id,'title',e.target.value)}/></label><label className="field">Inquiry question<textarea rows={2} value={lesson.inquiry} onChange={e=>updateLesson(lesson.id,'inquiry',e.target.value)} placeholder="What meaningful question will guide this experience?"/></label><label className="field">What might students do?<textarea rows={3} value={lesson.experience} onChange={e=>updateLesson(lesson.id,'experience',e.target.value)} placeholder="Describe an investigation, discussion, observation or making experience."/></label><label className="field">What evidence of understanding will you look for?<textarea rows={2} value={lesson.evidence} onChange={e=>updateLesson(lesson.id,'evidence',e.target.value)} placeholder="What might students say, do, make or explain?"/></label><label className="field">Where do students have voice or choice?<textarea rows={2} value={lesson.choice} onChange={e=>updateLesson(lesson.id,'choice',e.target.value)} placeholder="How can students influence the direction or outcome?"/></label></section>)}<div className="actions"><button className="btn light" onClick={addLesson}><Plus size={15}/> Add learning experience</button><button className="btn primary" onClick={save}><Save size={15}/> Save sequence</button></div></div>} {page==='Scenario Lab'&&<div className="page narrow"><div className="intro"><div className="eyebrow">STEP 04 · PRACTISE THE UNEXPECTED</div><h1>Scenario Lab</h1><p>Practise responding to moments that do not fit neatly into a lesson plan. These are curated demo scenarios for now; genuinely dynamic scenarios and personalised AI feedback will need a secure AI connection.</p></div><section className="scenarioPanel">{scenario?<><div className="scenarioHeader"><span className="copilotIcon"><Shuffle size={20}/></span><div><small>{scenario.type}</small><h2>{scenario.title}</h2></div></div><div className="scenarioSituation"><b>What happens</b><p>{scenario.context}</p></div><div className="scenarioQuestion"><b>Your challenge</b><p>{scenario.prompt}</p></div><label className="field">Your response<textarea rows={6} value={scenarioAnswer} onChange={e=>setScenarioAnswer(e.target.value)} placeholder="What would you do first, and why?"/></label><label className="field">Your reflection (optional)<textarea rows={3} value={scenarioReflection} onChange={e=>setScenarioReflection(e.target.value)} placeholder="What trade-offs are you considering?"/></label><div className="scenarioFollow"><b>Go deeper</b><p>{scenario.follow}</p></div><div className="heroActions"><button className="btn primary" onClick={saveScenario}><Save size={15}/> Save response</button><button className="btn light" onClick={generateScenario}>Try another <Shuffle size={14}/></button></div></>:<div className="scenarioEmpty"><p>You will not see a suggested answer before you respond. Practise making a reasoned decision, not guessing a hidden correct answer.</p><button className="btn primary big" onClick={generateScenario}><Shuffle size={16}/> Generate practice scenario</button></div>}</section><section className="portfolio"><div className="sectionHeading"><div><h2>Your practice portfolio</h2><p>Saved in this browser on this device.</p></div><span className="tag">{scenarioHistory.length} saved</span></div>{scenarioHistory.length?scenarioHistory.map((item,i)=><article className="portfolioItem" key={i}><small>{item.date}</small><h3>{item.scenario.split('\n')[0]}</h3><p><b>Your response</b><br/>{item.answer}</p>{item.reflection&&<p><b>Your reflection</b><br/>{item.reflection}</p>}<button className="btn light" onClick={()=>{if(window.confirm('Delete this portfolio entry?'))setScenarioHistory(items=>items.filter((_,j)=>j!==i))}}><Trash2 size={14}/> Delete</button></article>):<p className="muted">Saved reflections will appear here after your first response.</p>}</section><div className="note"><Lightbulb/><div><b>AI feedback is a later connection</b><p>The planned AI coach will respond to your actual answer, explain trade-offs and link feedback to your selected POI and unit plan. For now, save your reasoning and revisit it as you learn.</p></div></div></div>}
 {page==='Teach & review'&&<div className="page narrow"><div className="intro"><div className="eyebrow">FROM PREPARATION TO REFLECTION</div><h1>Teach, notice, respond, reflect.</h1><p>Use this online form before, during and after teaching. Update it as students reveal what they need next.</p></div><section className="formSection"><h2><span>01</span> Before teaching</h2><label className="field">Planning context<textarea rows={3} value={plan.context} onChange={e=>update('context',e.target.value)} placeholder="Curriculum links, class context, learner strengths and needs, relevant prior learning."/></label><label className="field">Learning goals<textarea rows={3} value={plan.learningGoals} onChange={e=>update('learningGoals',e.target.value)} placeholder="What knowledge, conceptual understanding and skills should students develop?"/></label><label className="field">Success criteria<textarea rows={3} value={plan.successCriteria} onChange={e=>update('successCriteria',e.target.value)} placeholder="What might students say, do, make or explain if they are progressing?"/></label><label className="field">Resources and preparation<textarea rows={3} value={plan.resources} onChange={e=>update('resources',e.target.value)} placeholder="Materials, texts, local resources, grouping, accessibility and differentiation."/></label></section><section className="formSection"><h2><span>02</span> During teaching</h2><label className="field">Teaching notes and adaptations<textarea rows={4} value={plan.teachingNotes} onChange={e=>update('teachingNotes',e.target.value)} placeholder="What did you actually do? What changed in response to student questions or needs?"/></label><label className="field">Evidence of learning observed<textarea rows={4} value={plan.evidenceCollected} onChange={e=>update('evidenceCollected',e.target.value)} placeholder="Record specific student statements, strategies, work samples, misconceptions or transfer."/></label><label className="field">Student voice and emerging questions<textarea rows={3} value={plan.studentVoice} onChange={e=>update('studentVoice',e.target.value)} placeholder="What did students ask, choose, challenge or suggest? How did their ideas influence learning?"/></label></section><section className="formSection"><h2><span>03</span> After teaching</h2><label className="field">Teacher reflection<textarea rows={4} value={plan.reflection} onChange={e=>update('reflection',e.target.value)} placeholder="What did students understand? What evidence supports this? What surprised you?"/></label><label className="field">Next steps and changes for next time<textarea rows={4} value={plan.nextSteps} onChange={e=>update('nextSteps',e.target.value)} placeholder="What should be revisited, extended, retaught or changed? What new inquiry might emerge?"/></label><label className="field">Assessment and evidence plan<textarea rows={3} value={plan.assessment} onChange={e=>update('assessment',e.target.value)} placeholder="Formative checks, student work, conversations, demonstrations or summative evidence."/></label></section><div className="actions"><button className="btn light" onClick={()=>setPage('Planning journey')}>Back to journey</button><button className="btn primary" onClick={save}><Save size={15}/> Save teaching record</button></div></div>}{page==='Learning guide'&&<div className="page narrow"><div className="intro"><div className="eyebrow">PYP FOUNDATIONS</div><h1>Learn the PYP, one idea at a time.</h1><p>Introductory explanations for planning. Use current official IB resources and your school’s guidance alongside this starter guide.</p></div><div className="guideList">{guides.map((guide,i)=><article className={`guide guideAccordion ${openGuide===i?'isOpen':''}`} key={guide.title}><button className="guideTrigger" aria-expanded={openGuide===i} onClick={()=>setOpenGuide(openGuide===i?null:i)}><span className="guideNumber">{String(i+1).padStart(2,'0')}</span><span className="guideTriggerText"><strong>{guide.title}</strong><small>{guide.summary}</small></span><ChevronRight className="guideChevron" size={19}/></button>{openGuide===i&&<div className="guideDetail"><h4>Understanding this in depth</h4>{guide.detail.map((paragraph,j)=><p key={j}>{paragraph}</p>)}<div className="guideScenario"><b><Sparkles size={15}/> Classroom scenario</b><p>{guide.scenario}</p></div><h4>Questions to think about</h4><ul>{guide.questions.map((q,j)=><li key={j}>{q}</li>)}</ul><div className="guidePractice"><b>Try it in your own planning</b><p>{guide.practice}</p></div></div>}</article>)}</div><div className="note"><BookOpen/><div><b>Explore official guidance</b><p>For current programme terminology and requirements, consult the IB’s official PYP resources.</p><a href="https://www.ibo.org/programmes/primary-years-programme/" target="_blank" rel="noreferrer">Official PYP programme ↗</a></div></div></div>}
 {page==='Print plan'&&<div className={`page printPage printChoice-${printChoice}`}><div className="intro noPrint"><div className="eyebrow">TWOWISEOLDOWLS · PYP UNIT PLANNING PACK</div><h1>{plan.title||'Untitled unit'}</h1><p>Year group: {plan.year} · Theme: {plan.theme||'Not selected'} · Duration: {plan.duration}</p><p>A branded PYP-aligned unit planning pack with collaboration and student agency records. The Programme of Inquiry is managed and printed separately. Independent learning templates, not official IB forms.</p><div className="printCentre noPrint"><label htmlFor="printChoice">Print</label><select id="printChoice" value={printChoice} onChange={e=>setPrintChoice(e.target.value)}><option value="all">Everything</option><option value="unit">Complete unit planner</option><option value="overview">Unit overview</option><option value="design">Purpose and inquiry design</option><option value="sequence">Learning and teaching sequence</option><option value="assessment">Assessment and evidence</option><option value="reflection">Teaching reflection</option><option value="collaboration">Collaborative planning record</option><option value="agency">Student voice, agency and action</option></select><button className="btn primary" onClick={()=>window.print()}><Download size={15}/> Print selection / Save as PDF</button></div></div><section data-print-section="overview" className="printSection printForm"><div className="printBrand"><div className="printBrandMark"><OwlMark/></div><div className="printBrandText"><strong>TwoWiseOldOwls</strong><span>PYP Unit Planning Studio</span></div><div className="printBrandMeta">UNIT OF INQUIRY<br/>PLANNING RECORD</div></div><div className="formKicker">FORM 01 OF 05</div><h2>Unit overview and context</h2><p className="formPurpose">What is the context for this inquiry, and who are the learners?</p><div className="teamReview"><b>Planning record</b><div className="teamLines"><span>Class / grade:</span><span>Planning date:</span></div><div className="teamLines"><span>Classroom teacher(s):</span><span>Specialist / support colleagues:</span></div><div className="teamLines"><span>Review date:</span><span>Version:</span></div><p>Use with the relevant teaching team. Record local curriculum requirements and learner context before finalizing the unit.</p></div>{[{t:'Unit title',v:plan.title},{t:'Year group',v:plan.year},{t:'Transdisciplinary theme',v:plan.theme},{t:'Proposed duration',v:plan.duration},{t:'Planning context and curriculum connections',v:plan.context},{t:'Prior knowledge and student questions',v:plan.priorKnowledge},{t:'Resources and preparation',v:plan.resources}].map(x=><div className="printField" key={x.t}><h3>{x.t}</h3><p>{x.v||'Not yet completed'}</p></div>)}</section><section data-print-section="design" className="printSection printForm"><div className="printBrand"><div className="printBrandMark"><OwlMark/></div><div className="printBrandText"><strong>TwoWiseOldOwls</strong><span>PYP Unit Planning Studio</span></div><div className="printBrandMeta">UNIT OF INQUIRY<br/>PLANNING RECORD</div></div><div className="formKicker">FORM 02 OF 05</div><h2>Purpose and inquiry design</h2><p className="formPurpose">What do we want students to understand, and how will they explore it?</p><div className="collabPrompt"><b>Collaborative checkpoint · Classroom and specialist teachers</b><p>Agree that the central idea is transferable, lines of inquiry explore distinct aspects of it, and subject knowledge and skills genuinely connect to the inquiry. Note questions or disagreements before the team agrees the draft.</p><div className="blankLines">Team notes / agreed changes: ______________________________________________________________<br/>________________________________________________________________________________________</div></div>{[{t:'Central idea',v:plan.centralIdea},{t:'Lines of inquiry',v:plan.lines},{t:'Key concepts',v:plan.concepts},{t:'Learner profile attributes',v:plan.learnerProfile},{t:'Approaches to learning (ATL)',v:plan.atl},{t:'Learning goals',v:plan.learningGoals},{t:'Success criteria',v:plan.successCriteria}].map(x=><div className="printField" key={x.t}><h3>{x.t}</h3><p>{x.v||'Not yet completed'}</p></div>)}</section><section data-print-section="sequence" className="printSection printForm"><div className="printBrand"><div className="printBrandMark"><OwlMark/></div><div className="printBrandText"><strong>TwoWiseOldOwls</strong><span>PYP Unit Planning Studio</span></div><div className="printBrandMeta">UNIT OF INQUIRY<br/>PLANNING RECORD</div></div><div className="formKicker">FORM 03 OF 05</div><h2>Learning and teaching sequence</h2><p className="formPurpose">How might the inquiry unfold? Adapt the sequence in response to students.</p><div className="collabPrompt"><b>Collaborative checkpoint · Before teaching and during the unit</b><p>Coordinate the sequence with colleagues. Revisit it as student questions, evidence and unexpected learning emerge; do not treat the sequence as fixed.</p></div>{lessons.map((l,i)=><div className="printLesson" key={l.id}><h3>{i+1}. {l.title}</h3><p><b>Inquiry question:</b> {l.inquiry||'Not yet completed'}</p><p><b>Learning experience:</b> {l.experience||'Not yet completed'}</p><p><b>Resources / preparation:</b> {plan.resources||'Not yet completed'}</p><p><b>Student voice and choice:</b> {l.choice||'Not yet completed'}</p></div>)}</section><section data-print-section="assessment" className="printSection printForm"><div className="printBrand"><div className="printBrandMark"><OwlMark/></div><div className="printBrandText"><strong>TwoWiseOldOwls</strong><span>PYP Unit Planning Studio</span></div><div className="printBrandMeta">UNIT OF INQUIRY<br/>PLANNING RECORD</div></div><div className="formKicker">FORM 04 OF 05</div><h2>Assessment and evidence of learning</h2><p className="formPurpose">What evidence will show progress towards the intended understanding?</p><div className="collabPrompt"><b>Collaborative checkpoint · Agree on evidence</b><p>Discuss what understanding will look like, what each teacher will observe, and how evidence will inform next teaching steps. Include language development and different learner needs.</p></div>{[{t:'Assessment plan',v:plan.assessment},{t:'Learning goals',v:plan.learningGoals},{t:'Success criteria',v:plan.successCriteria},{t:'Evidence observed during teaching',v:plan.evidenceCollected},{t:'Student voice and emerging questions',v:plan.studentVoice},{t:'Student agency, choice and possible action',v:plan.agency}].map(x=><div className="printField" key={x.t}><h3>{x.t}</h3><p>{x.v||'Not yet completed'}</p></div>)}{lessons.map((l,i)=><div className="printField" key={l.id}><h3>Evidence for experience {i+1}: {l.title}</h3><p>{l.evidence||'Not yet completed'}</p></div>)}</section><section data-print-section="reflection" className="printSection printForm"><div className="printBrand"><div className="printBrandMark"><OwlMark/></div><div className="printBrandText"><strong>TwoWiseOldOwls</strong><span>PYP Unit Planning Studio</span></div><div className="printBrandMeta">UNIT OF INQUIRY<br/>PLANNING RECORD</div></div><div className="formKicker">FORM 05 OF 05</div><h2>Teaching reflection and next steps</h2><p className="formPurpose">What did students understand, what changed, and what should happen next?</p><div className="collabPrompt"><b>Collaborative checkpoint · After teaching</b><p>Invite reflections from all teachers involved. Use student work and observations as evidence; identify what to retain, adapt or investigate next time.</p><div className="teamLines"><span>Teachers contributing to reflection:</span><span>Reflection date:</span></div></div>{[{t:'Teaching notes and adaptations',v:plan.teachingNotes},{t:'Teacher reflection',v:plan.reflection},{t:'What evidence shows student understanding?',v:plan.evidenceCollected},{t:'How did student voice influence the inquiry?',v:plan.studentVoice},{t:'Next steps and changes for next time',v:plan.nextSteps}].map(x=><div className="printField" key={x.t}><h3>{x.t}</h3><p>{x.v||'Not yet completed'}</p></div>)}</section><section data-print-section="collaboration" className="printSection printForm"><div className="printBrand"><div className="printBrandMark"><OwlMark/></div><div className="printBrandText"><strong>TwoWiseOldOwls</strong><span>PYP Unit Planning Studio</span></div><div className="printBrandMeta">TEAM DISCUSSION<br/>AND DECISIONS</div></div><div className="formKicker">DOCUMENT 07 · COLLABORATIVE PLANNING RECORD</div><h2>Collaborative planning record</h2><p className="formPurpose">Use this record during team meetings to make professional dialogue and agreed decisions visible.</p><div className="teamReview"><b>Meeting details</b><div className="teamLines"><span>Date / time:</span><span>Year level / unit:</span></div><div className="teamLines"><span>Teachers present:</span><span>Next meeting:</span></div></div>{[{t:'Purpose of this meeting',v:'What planning decision or learning evidence are we discussing?'},{t:'Questions, perspectives and evidence shared',v:'Record different perspectives, student evidence and unresolved questions.'},{t:'Agreed decisions and rationale',v:'What did the team agree, and why?'},{t:'Actions and responsibilities',v:'Who will do what, and by when?'},{t:'Items requiring follow-up',v:'What needs further discussion or school-level guidance?'}].map(x=><div className="writeField" key={x.t}><h3>{x.t}</h3><p>{x.v}</p><div className="writingLines"></div><div className="writingLines"></div><div className="writingLines"></div></div>)}</section><section data-print-section="agency" className="printSection printForm"><div className="printBrand"><div className="printBrandMark"><OwlMark/></div><div className="printBrandText"><strong>TwoWiseOldOwls</strong><span>PYP Unit Planning Studio</span></div><div className="printBrandMeta">STUDENT VOICE<br/>AND AGENCY</div></div><div className="formKicker">DOCUMENT 08 · STUDENT VOICE, AGENCY AND ACTION</div><h2>Student voice, agency and action record</h2><p className="formPurpose">Capture how students' questions, choices, ideas and emerging action influence the inquiry. Complete during the unit, not only at the end.</p>{[{t:'Student questions and wonderings',v:plan.priorKnowledge},{t:'Choices students made or influenced',v:plan.agency},{t:'Changes made to the inquiry in response to students',v:plan.studentVoice},{t:'Action or application emerging from learning',v:'Record actions that are meaningful, age-appropriate and connected to learning; action is not a compulsory preselected project.'},{t:'What will we follow up next?',v:plan.nextSteps}].map(x=><div className="printField" key={x.t}><h3>{x.t}</h3><p>{x.v||'Record during teaching'}</p></div>)}</section><div className="note noPrint"><Lightbulb/><div><b>Ready to print?</b><p>Choose Print planning pack / Save as PDF. Each major document starts on a new A4 page. The Programme of Inquiry is a school-level working overview and must be completed collaboratively.</p></div></div></div>}{page==='Quality check'&&<div className="page narrow"><div className="intro"><div className="eyebrow">GUIDED MENTOR REVIEW · DRAFT FEEDBACK</div><h1>Make your planning stronger.</h1><p>This beginner-friendly review checks whether key planning pieces are present and offers questions to help you think like a reflective PYP practitioner. It is a planning aid, not an official IB assessment or a substitute for school guidance.</p></div><div className="review"><div><small>PLANNING FOUNDATIONS STARTED</small><h2>{started} <span>/ 6</span></h2><p>Completeness is a starting point. Quality comes from the connections between your ideas and what learners actually do.</p></div><div className="percent">{Math.round(mentorChecks.filter(x=>x.ok).length/mentorChecks.length*100)}%</div></div><div className="mentorIntro"><Sparkles size={19}/><div><b>Your planning mentor prompts</b><p>These prompts are generated from the draft you have entered. They are guided checks, not AI-generated feedback yet.</p></div></div><div className="mentorChecks">{mentorChecks.map((item,i)=><section className="mentorCheck" key={item.title}><div className="mentorCheckTop"><span className={item.ok?'statusDot good':'statusDot'}>{item.ok?'✓':String(i+1).padStart(2,'0')}</span><div><h3>{item.title}</h3><small>{item.ok?'STARTED — REVIEW THE QUALITY':'NEXT STEP TO CONSIDER'}</small></div></div><p>{item.tip}</p><button className="btn light" onClick={()=>setPage(item.page)}>{item.label}<ChevronRight size={14}/></button></section>)}</div><div className="note"><Lightbulb/><div><b>Use the questions, not just the score</b><p>A well-filled form does not automatically make a strong inquiry unit. Revisit the links between the central idea, lines of inquiry, learning experiences and evidence of understanding. Then revise after listening to students.</p></div></div><button className="btn primary" onClick={()=>setPage('Planning journey')}>Return to planning journey <ChevronRight size={15}/></button></div>}
 <footer>Personal learning workspace · Independent planning aid, not an IB product</footer></main>
 {help&&<div className="overlay" onClick={()=>setHelp(null)}><section className="modal" onClick={e=>e.stopPropagation()}><button className="close" onClick={()=>setHelp(null)}>×</button><div className="eyebrow">BEGINNER’S NOTE</div><h2>{help}</h2><p>{help==='Transdisciplinary theme'?'The PYP has six transdisciplinary themes. They provide broad ways to explore the world and human experience. Choose one that fits the understanding at the heart of your unit.':guides.find(([t])=>help.includes(t))?.[1]||sections.find(s=>s.title===help)?.hint||'Use this section to make your thinking explicit. Ask what you want students to understand, how they will explore it, and what evidence will show learning.'}</p><button className="btn primary" onClick={()=>setHelp(null)}>Got it</button></section></div>}
 </div>
}
export default App;